const initialState = {
  items: [],
  total: 0,
  subtotal: 0,
  tax: 0,
  discount: 0,
  shipping: 0,
  grandTotal: 0
};

const cartSlice = createSlice({
  name: 'cart',
  initialState,
  reducers: {
